#!/usr/bin/env python3
"""Promote the index-3/2 Lane–Emden headline, its simulator, certificates and existence proof from
Work/Math to Checked/Math (run 2026-11-19T1028Z; pattern of runs/2026-11-19T0428Z/scripts/promote_le4.py).

Mechanical copy: namespaces Work.Math -> Checked.Math, `import Mathlib` -> specific modules, module docs
replaced by number-free text (check_prose rule 7). Statements and proofs otherwise byte-identical."""
import pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
W, C = ROOT / "Work/Math", ROOT / "Checked/Math"
MODS = ["LEGStart", "LE32Cell", "LE32CellQ", "LE32Glue", "LE32QData", "LE32Chain", "LaneEmden32",
        "LE32ExistsLeft", "LE32ExistsRight", "LE32Exists"]
G = "`runs/2026-11-19T1028Z/scripts/emit_le32.py`"
P = "Promoted verbatim from `Work/Math/{m}.lean`."
DOCS = {
 "LEGStart": "Lane–Emden-type equation with any nonlinearity Lipschitz near the reference: the singular start. `start` encloses every solution with central value one (θ differentiable with derivative φ, φ continuous at the centre) near a polynomial reference whose residual is bounded by a multiple of the squared radius; closed by continuous induction. Generalised from `Checked.Math.LENStart` (integer index) for the fractional index three halves.",
 "LE32Cell": "Lane–Emden equation of index three halves: the nonlinearity θ to the power three halves as `g32 θ`, the cube of the square root (equal to Mathlib's real power for every real θ, `rpow32_eq`), its Lipschitz bound on a slab (`g32_lip`), the closeness of `g32 x` to the cube of `y` from a certificate that the square of `y` is close to `x` (`g32_close`), and the validated cell step `cell` (Grönwall, generic tube lemma `Checked.Math.LENCell.tube_cell_t`).",
 "LE32CellQ": "Lane–Emden equation of index three halves: the validated cells of `Checked.Math.LE32Cell.cell` checked by kernel evaluation. All side conditions and both defect bounds of a cell are one proposition over the rationals (`CellProp`); the power of the Taylor polynomial is replaced in the defect by the cube of a polynomial `pw` whose square is certified close to it and which is bounded away from zero, and in a cell next to the zero of θ (`pw` empty) it is bounded crudely. The chain lemmas are those of `Checked.Math.LENCellQ` with this field.",
 "LE32Glue": "Lane–Emden equation of index three halves: the singular start (`start32`, the generic start of `Checked.Math.LEGStart` with a residual certified through the square-root polynomial) and the last cell (`last32`: sign change of θ, φ negative, bounds on the mass factor), each from one proposition over the rationals decided by kernel evaluation; `qeqB` compares coefficient lists with order relations only.",
 "LE32QData": f"Generated by {G}: the singular start and the validated cells of the Lane–Emden chain of index three halves as data; every side condition, defect bound and link decided by kernel evaluation over the rationals, one declaration per segment of cells.",
 "LE32Chain": f"Generated by {G}: chaining of the singular start, the kernel-checked segments and the last cell of the Lane–Emden chain of index three halves.",
 "LE32ExistsLeft": "Lane–Emden equation of index three halves, existence near the centre: Banach fixed point of the scaled Volterra map with the clamped power three halves (the index-three construction `Checked.Math.LEExistsLeft`, whose constants bound this power too).",
 "LE32ExistsRight": "Lane–Emden equation of index three halves, existence away from the centre: Picard–Lindelöf for the clamped field; the clamped energy is nonincreasing and the potential part is not negative, so the clamp on φ stays inactive, and the bound on θ' keeps the clamp on θ inactive (adapted from `Checked.Math.LEExistsRight`).",
 "LE32Exists": "Lane–Emden equation of index three halves: existence of a solution meeting every hypothesis of `Checked.Math.LaneEmden32.laneEmden32_constants` (left piece by a fixed point, right piece by Picard–Lindelöf for the clamped field with the clamps inactive by the energy, glued).",
}
for m in MODS:
    s = (W / f"{m}.lean").read_text()
    s = s.replace("Work.Math.", "Checked.Math.")
    assert "Work." not in s, m
    if m == "LaneEmden32":
        s = s.replace("import Mathlib\n", "import Mathlib.Analysis.Calculus.Deriv.MeanValue\nimport Mathlib.Topology.Order.IntermediateValue\n", 1)
        s = s.replace("frozen before proof, run 2026-11-19T1028Z", "frozen before proof in `Work/Math/LaneEmden32.lean`, statement promoted\nbyte-identical")
        s = s.replace("Existence of such a θ is a separate theorem (to do).",
                      "Existence of such a θ:\n`Checked.Math.LE32Exists.exists_solution` (non-vacuity witness in `Checked/Trust/Witnesses.lean`).")
        i = s.index("\n\n**Proof** (run"); j = s.index("-/", i)
        s = s[:i] + "\n" + s[j:]
        assert "to do" not in s
    else:
        assert "import Mathlib\n" not in s, m
        i = s.index("/-!")
        j = s.index("-/", i) + 2
        s = s[:i] + "/-! " + DOCS[m] + " " + P.format(m=m) + " -/" + s[j:]
    (C / f"{m}.lean").write_text(s)
    print("wrote", m)
